<?php
declare(strict_types=1);
namespace App\Application\Taxonomy\Service;
use App\Application\Taxonomy\DTO\Request\ListTaxonomySubjectsRequestDto;use App\Application\Taxonomy\DTO\Response\PaginatedTaxonomySubjectsResponseDto;use App\Application\Taxonomy\Mapper\TaxonomySubjectResponseMapper;use App\Domain\Taxonomy\Repository\TaxonomySubjectRepositoryInterface;
final class ListTaxonomySubjectsService { public function __construct(private readonly TaxonomySubjectRepositoryInterface $subjects,private readonly TaxonomySubjectResponseMapper $mapper){} public function list(ListTaxonomySubjectsRequestDto $input):PaginatedTaxonomySubjectsResponseDto{ $items=$this->subjects->list($input->offset(),$input->perPage); $all=$this->subjects->list(0,1000); $direct=$this->subjects->questionCountsBySubjectId(); $parents=[]; foreach($all as $subject)$parents[$subject->id]=$subject->parentId; $aggregated=$direct; foreach($direct as $id=>$total){$parent=$parents[$id]??null; while($parent!==null){$aggregated[$parent]=($aggregated[$parent]??0)+$total;$parent=$parents[$parent]??null;}} return new PaginatedTaxonomySubjectsResponseDto(array_map(fn($subject)=>$this->mapper->toResponse($subject,$aggregated[$subject->id]??0),$items),$input->page,$input->perPage,$this->subjects->count());} }
